#include <IOKit/IOLocks.h>
#include <mach/vm_types.h>
#include <mach/vm_param.h>
extern "C" { extern const pmap_t kernel_pmap; extern ppnum_t pmap_find_phys(pmap_t, addr64_t); }
static_assert(sizeof(void*)==8 && sizeof(uintptr_t)==8,"ARM64 pointers");
static_assert(sizeof(lck_mtx_t)==16 && alignof(lck_mtx_t)==8,"exact KDK mutex");
static_assert(sizeof(ppnum_t)==4 && sizeof(addr64_t)==8,"exact physical API");
static_assert(__is_same(decltype(&IOLockGetMachLock),lck_mtx_t*(*)(IOLock*)),"getter signature");
static_assert(__is_same(decltype(&pmap_find_phys),ppnum_t(*)(pmap_t,addr64_t)),"pmap signature");
extern "C" const uint64_t control_type_facts[]={sizeof(lck_mtx_t),alignof(lck_mtx_t),sizeof(ppnum_t),sizeof(addr64_t),sizeof(pmap_t)};
extern "C" ppnum_t (*const control_pmap_symbol)(pmap_t,addr64_t)=&pmap_find_phys;
extern "C" const pmap_t *const control_kernel_symbol=&kernel_pmap;
extern "C" lck_mtx_t *(*const control_lock_symbol)(IOLock*)=&IOLockGetMachLock;

